#!/bin/bash
# Round-2 source photos (2026-10-01), chosen against SOURCE_SELECTION.md +
# scripts/portraits/SOURCE_RULES.md: in-game regular uniform, McCain-level
# energy (McCain = 7/10), large unobstructed face, current team preferred.
# Candidates were found with Google Images restricted to site:nba.com
# (NBA.com articles / game pages and team sites, Getty/NBAE photos, no
# watermark) and scored by eye. Rerunning this script re-downloads the same
# photos and rewrites the source fields in assets/players/metadata/.
# Scores: clarity,size,expression,occlusion,angle,recency,jersey.
# Crops (x,y,size in stored-image pixels) are added with --crop once chosen.
# Round-1 picks: selections-round1.sh (rejected by user feedback 2026-10-01).
set -u
cd "$(dirname "$0")/../.."
run() { node scripts/portraits/select-source.js --supersede "user feedback 2026-10-01" "$@" || echo "FAILED: $2"; }
run_rep() { node scripts/portraits/select-source.js --supersede "user: head tipped back, too wild at thumbnail size" "$@" || echo "FAILED: $2"; }

# Round 3 (2026-10-01): replaced the round-2 pick (head tipped back) per user feedback.
